$(document).ready(function () {
    // Estrutura de dados para as opções
    const tiposDeUnidade = {
        'Hospital': ['Hospital geral', 'Hospital Infantil', 'Hospital Maternidade'],
        'Clinica': ['Clinica ambulatorial', 'Clinica reabilitação', 'Clinica pequenas cirurgias'],
        'Laboratório': ['Laboratório de análises clínicas', 'Laboratório de imagens'],
        'Remoção': ['Remoção adulto', 'Remoção infantil', 'Remoção neonatal'],
        'Pronto atendimento': []
    };

    // Inicialização dos elementos
    const unidadeSelect = document.getElementById('unidade');
    const tipoUnidadeGroup = document.getElementById('tipoUnidadeGroup');
    const tipoUnidadeButton = tipoUnidadeGroup.querySelector('.multiselect-button');
    const tipoUnidadeOptions = tipoUnidadeGroup.querySelector('.multiselect-options');

    // Máscaras para os campos
    $(".lp-cuidae-form-wrapper #telefone").mask("(00) 00000-0000");
    $(".lp-cuidae-form-wrapper #cnpj").mask("00.000.000/0000-00");
    $(".lp-cuidae-form-wrapper #cnes").mask("0000000");

    // Função para atualizar o texto do botão do "select" de tipo de unidade
    function updateButtonText() {
        const selectedCheckboxes = tipoUnidadeOptions.querySelectorAll('input[type="checkbox"]:checked');
        const selectedCount = selectedCheckboxes.length;

        if (selectedCount === 0) {
            tipoUnidadeButton.textContent = '*Selecione';
        } else if (selectedCount === 1) {
            tipoUnidadeButton.textContent = selectedCheckboxes[0].value;
        } else {
            tipoUnidadeButton.textContent = `${selectedCount} opções selecionadas`;
        }
    }

    // Função para renderizar as opções do "select" de tipo de unidade
    function renderTipoUnidadeOptions(options) {
        tipoUnidadeOptions.innerHTML = '';
        if (options && options.length > 0) {
            options.forEach(option => {
                const label = document.createElement('label');
                label.innerHTML = `<input type="checkbox" name="tipoUnidade[]" value="${option}"> ${option}`;
                tipoUnidadeOptions.appendChild(label);
            });
            const checkboxes = tipoUnidadeOptions.querySelectorAll('input[type="checkbox"]');
            checkboxes.forEach(checkbox => {
                checkbox.addEventListener('change', updateButtonText);
            });
        }
        updateButtonText();
    }

    // Lógica para abrir/fechar o "select" customizado
    tipoUnidadeButton.addEventListener('click', function (e) {
        if (!this.disabled) {
            e.stopPropagation();
            tipoUnidadeOptions.classList.toggle('show');
        }
    });

    // Fechar o dropdown ao clicar fora
    document.addEventListener('click', function (e) {
        if (!tipoUnidadeGroup.contains(e.target)) {
            tipoUnidadeOptions.classList.remove('show');
        }
    });

    // Evento de 'change' no select de Unidade
    unidadeSelect.addEventListener('change', function () {
        const unidadeSelecionada = this.value;
        let opcoes = tiposDeUnidade[unidadeSelecionada] || [];

        let texto = '*Selecione';

        if (unidadeSelecionada === '') {
            tipoUnidadeButton.disabled = true;
            tipoUnidadeButton.classList.add('disabled-select');
        }
        else if (unidadeSelecionada === 'Pronto atendimento') {
            texto = 'Esta unidade não possui tipo';
            tipoUnidadeButton.disabled = true;
            tipoUnidadeButton.classList.add('disabled-select');
            opcoes = [];
        }
        else {
            tipoUnidadeButton.disabled = false;
            tipoUnidadeButton.classList.remove('disabled-select');
        }

        renderTipoUnidadeOptions(opcoes);
        tipoUnidadeButton.textContent = texto;
        tipoUnidadeOptions.classList.remove('show');
    });

    // Inicializa o select de tipo de unidade
    unidadeSelect.dispatchEvent(new Event('change'));

    // Evento de clique no botão enviar
    $(".lp-cuidae-form-wrapper .lp-cuidae-enviarBtn #submitBtn").click(function () {
        if (validateFields()) {
            enviarParaListaDinamica();
        }
    });
});

// Função de validação completa
function validateFields() {
    var isValid = true;

    // Validação dos campos obrigatórios
    isValid &= validateField(".lp-cuidae-form-wrapper #unidade");
    isValid &= validateTipoUnidade();

    isValid &= validateField(".lp-cuidae-form-wrapper #razaoSocial");
    isValid &= validateOnlyLetters(".lp-cuidae-form-wrapper #razaoSocial", "Razão Social");

    isValid &= validateField(".lp-cuidae-form-wrapper #nomeFantasia");
    isValid &= validateOnlyLetters(".lp-cuidae-form-wrapper #nomeFantasia", "Nome Fantasia");

    isValid &= validateField(".lp-cuidae-form-wrapper #responsavel");
    isValid &= validateOnlyLetters(".lp-cuidae-form-wrapper #responsavel", "Responsável");

    isValid &= validateField(".lp-cuidae-form-wrapper #telefone");
    isValid &= validateField(".lp-cuidae-form-wrapper #cnpj");
    isValid &= validateField(".lp-cuidae-form-wrapper #cnes");
    isValid &= validateField(".lp-cuidae-form-wrapper #email");
    isValid &= validateField(".lp-cuidae-form-wrapper #endereco");
    isValid &= validateField(".lp-cuidae-form-wrapper #estado");

    isValid &= validateField(".lp-cuidae-form-wrapper #cidade");
    isValid &= validateOnlyLetters(".lp-cuidae-form-wrapper #cidade", "Cidade");

    isValid &= validateField(".lp-cuidae-form-wrapper #comentario");

    // Validações específicas
    isValid &= validateEmail(".lp-cuidae-form-wrapper #email");
    isValid &= validateCNPJ(".lp-cuidae-form-wrapper #cnpj");

    // Validação do reCAPTCHA
    isValid &= validateRecaptcha();

    if (!isValid) {
        scrollIntoViewAdjusted($('.lp-cuidae-form-wrapper .error-message')[0], 200);
    }

    return isValid;
}

// Função para validar campos obrigatórios
function validateField(selector) {
    removeError(selector);

    if ($(selector).val() == undefined || $(selector).val().trim() === "") {
        $("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    return true;
}

// Função para validar apenas letras corretamente
function validateOnlyLetters(selector, fieldName) {
    removeError(selector);

    const value = $(selector).val().trim();

    // Se estiver vazio, não executa essa validação (campo obrigatório já lida com isso)
    if (value === ""){ 
			$("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
        $(selector).addClass("error-border").focus();
        return false;		
		}

    const regex = /^[A-Za-zÀ-ú\s]+$/;

    if (!regex.test(value)) {
        $("<p class='error-message'>*" + fieldName + " deve conter apenas letras</p>").insertAfter(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    return true;
}

// Funções de validação existentes
function validateTipoUnidade() {
    const unidadeSelect = $("#unidade").val();

    $('.lp-cuidae-form-wrapper #tipoUnidadeGroup .error-message').remove();

    if (unidadeSelect && unidadeSelect !== "Pronto atendimento") {
        const selectedTypes = document.querySelectorAll('#tipoUnidadeGroup input[type="checkbox"]:checked');
        if (selectedTypes.length === 0) {
            $("<p class='error-message'>*Selecione pelo menos um tipo de unidade</p>")
                .appendTo('.lp-cuidae-form-wrapper #tipoUnidadeGroup');
            return false;
        }
    }

    return true;
}

function validateEmail(selector) {
    if ($(selector).val().trim() === "") return true;

    removeError(selector);
    var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!emailRegex.test($(selector).val().trim())) {
        $("<p class='error-message'>*Digite um e-mail válido</p>").insertAfter(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    return true;
}

function validateCNPJ(selector) {
    if ($(selector).val().trim() === "") return true;

    removeError(selector);
    const cnpj = $(selector).val().replace(/[^\d]/g, '');

    if (cnpj.length !== 14) {
        $("<p class='error-message'>*CNPJ deve ter 14 dígitos</p>").insertAfter(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    return true;
}

function validateRecaptcha() {
    $('.lp-cuidae-form-wrapper .lp-cuidae-recaptcha-container .error-message').remove();

    var recaptchaResponse = grecaptcha.getResponse();

    if (!recaptchaResponse || recaptchaResponse.length === 0) {
        $("<p class='error-message'>*Por favor, confirme que você não é um robô</p>")
            .appendTo('.lp-cuidae-form-wrapper .lp-cuidae-recaptcha-container');
        return false;
    }

    return true;
}

function removeError(selector) {
    $(selector).nextAll(".error-message").remove();
    $(selector).removeClass("error-border");
}

function scrollIntoViewAdjusted(elem, offset = 0) {
    try {
        if (elem) {
            window.scrollBy({
                top: elem.getBoundingClientRect().top - offset,
                behavior: "smooth"
            });
        }
    } catch (error) {
        console.error("Erro ao dar scroll até o campo inválido:", error);
    }
}

// Função para obter tipos de unidade selecionados
function getTiposUnidadeSelecionados() {
    const selectedTypes = [];
    const checkboxes = document.querySelectorAll('#tipoUnidadeGroup input[type="checkbox"]:checked');
    checkboxes.forEach(checkbox => {
        selectedTypes.push(checkbox.value);
    });
    return selectedTypes.join(', ');
}

function getHorarioContato() {
    const horarios = [];
    $('input[name="horario"]:checked').each(function () {
        horarios.push($(this).val());
    });
    return horarios.join(', ');
}

function getFormaContato() {
    const formas = [];
    $('input[name="contato"]:checked').each(function () {
        formas.push($(this).val());
    });
    return formas.join(', ');
}

function enviarParaListaDinamica() {
    $(".lp-cuidae-form-wrapper #submitBtn").prop('disabled', true).text('Enviando...');
    $(".lp-cuidae-form-wrapper #loadingDiv").show();

    const preFixoAssuntoEmail = "Novo Lead";
    const unidade = $("#unidade").val() || "N/A";
    const tipoUnidade = getTiposUnidadeSelecionados() || "N/A";
    const nomeFantasia = $("#nomeFantasia").val() || "N/A";

    const subjectParts = [preFixoAssuntoEmail];

    if (unidade) subjectParts.push(unidade);
    if (tipoUnidade) subjectParts.push(tipoUnidade);
    if (nomeFantasia) subjectParts.push(nomeFantasia);

    const subject = subjectParts.join(" - ");

    const template = `
    <body>
    <div>
        <p>Segue novo cadastro de unidade através da LP Cuidae:</p>
        <p><strong>DADOS DA UNIDADE</strong></p>
        <div>
            <div><strong>Unidade:</strong> ${$("#unidade option:selected").text()}</div>
            <div><strong>Tipo de Unidade:</strong> ${getTiposUnidadeSelecionados()}</div>
            <div><strong>Razão Social:</strong> ${$("#razaoSocial").val()}</div>
            <div><strong>Nome Fantasia:</strong> ${$("#nomeFantasia").val()}</div>
            <div><strong>CNPJ:</strong> ${$("#cnpj").val()}</div>
            <div><strong>CNES:</strong> ${$("#cnes").val()}</div>
        </div>
        <p><strong>DADOS DO RESPONSÁVEL</strong></p>
        <div>
            <div><strong>Nome:</strong> ${$("#responsavel").val()}</div>
            <div><strong>Telefone:</strong> ${$("#telefone").val()}</div>
            <div><strong>E-mail:</strong> ${$("#email").val()}</div>
        </div>
        <p><strong>ENDEREÇO</strong></p>
        <div>
            <div><strong>Endereço Completo:</strong> ${$("#endereco").val()}</div>
            <div><strong>Estado:</strong> ${$("#estado option:selected").text()}</div>
            <div><strong>Cidade:</strong> ${$("#cidade").val()}</div>
        </div>
        <p><strong>PREFERÊNCIAS DE CONTATO</strong></p>
        <div>
            <div><strong>Melhor Horário:</strong> ${getHorarioContato()}</div>
            <div><strong>Melhor Forma de Contato:</strong> ${getFormaContato()}</div>
        </div>
        ${$("#comentario").val() ? `<p><strong>COMENTÁRIO</strong></p><div>${$("#comentario").val()}</div>` : ''}
    </div>
    </body>
    `;

    const cleanTemplate = template.replace(/\n/g, "").replace(/\s{2,}/g, " ");

    const data = {
        tabelaDinamica: "LPCuidae",
        internalEmail: configuration.emailInterno,
        subject: subject,
        groupId: window.__SITE__.codigo,
        companyId: '',
        userId: '',
        telefone: $("#telefone").val(),
        email: $("#email").val(),
        unidade: $("#unidade").val(),
        tipoUnidade: getTiposUnidadeSelecionados(),
        razaoSocial: $("#razaoSocial").val(),
        nomeFantasia: $("#nomeFantasia").val(),
        responsavel: $("#responsavel").val(),
        cnpj: $("#cnpj").val(),
        cnes: $("#cnes").val(),
        endereco: $("#endereco").val(),
        estado: $("#estado").val(),
        cidade: $("#cidade").val(),
        horarioContato: getHorarioContato(),
        formaContato: getFormaContato(),
        comentario: $("#comentario").val(),
        template: cleanTemplate
    };

    const apiURL = window.location.origin + "/api/servicos/generico/salvar-lista-enviar-email";

    console.log("Subject gerado:", subject);
    console.log("Dados enviados para API:", JSON.stringify(data, null, 2));

    $.ajax({
        url: apiURL,
        method: "POST",
        headers: {
            'Accept': 'application/json',
            'Content-Type': 'application/json'            
        },
        data: JSON.stringify(data),
        success: function (res, textStatus, jqXHR) {
            $(".lp-cuidae-form-wrapper #loadingDiv").hide();
            if (jqXHR.status === 200) {
                showSuccessMessage();
            } else {
                showErrorMessage("Erro ao salvar os dados.");
                resetSubmitButton();
            }
        },
        error: function (err) {
            console.error("Erro na requisição:", err);
            $(".lp-cuidae-form-wrapper #loadingDiv").hide();

            var errorMessage = "Erro técnico ao salvar os dados.";
            if (err.status === 400) errorMessage = "Dados inválidos. Verifique os campos preenchidos.";
            else if (err.status === 401) errorMessage = "Sessão expirada. Recarregue a página e tente novamente.";
            else if (err.status === 500) errorMessage = "Erro interno do servidor. Tente novamente em alguns minutos.";

            showErrorMessage(errorMessage);
            resetSubmitButton();
        }
    });
}

function showSuccessMessage() {
    $(".lp-cuidae-form-wrapper #formCadastroLpCuidae").hide();
    $(".lp-cuidae-form-wrapper #msgSucesso").css('display', 'flex');

    $(".lp-cuidae-form-wrapper #formCadastro input, .lp-cuidae-form-wrapper #formCadastro textarea, .lp-cuidae-form-wrapper #formCadastro select").each(function () {
        if ($(this).attr('type') === 'checkbox') $(this).prop('checked', false);
        else $(this).val('');
    });

    $('#tipoUnidadeGroup input[type="checkbox"]').prop('checked', false);
    $('.multiselect-button').text('*Selecione');

    grecaptcha.reset();
    scrollIntoViewAdjusted($('.lp-cuidae-form-wrapper #msgSucesso')[0], 100);
}

function showErrorMessage(message) {
    alert(message);
}

function resetSubmitButton() {
    $(".lp-cuidae-form-wrapper #submitBtn").prop('disabled', false).text('Enviar Cadastro');
};

