/*Script para tratar o comportamento quando esta no modo de edição da pagina, devido conflito com evetos*/

const FAQ_SELECTOR = '.pc-faq';
const EDIT_MODE_CLASS = 'has-edit-mode-menu';

const initializeFaqEditorFix = () => {
const isEditMode = document.body.classList.contains(EDIT_MODE_CLASS);

if (isEditMode) {
const faqContainer = fragmentElement.querySelector(FAQ_SELECTOR);

if (faqContainer) {
faqContainer.addEventListener('click', (event) => {
const button = event.target.closest('[data-toggle="collapse"]');

if (button) {
const targetSelector = button.getAttribute('data-target');
const $target = $(targetSelector);

if ($target.length) {
$target.collapse('toggle');
}
}
});
}
}
};

initializeFaqEditorFix();;

