$(document).ready(function () {
		// Máscaras para os campos
		$(".lp-ficaBem-form-wrapper #celular").mask("(00) 00000-0000");

		// Evento de clique no botão enviar
		/*$(".lp-ficaBem-form-wrapper .lp-ficaBem-enviarBtn #submitBtn").click(function () {
			if (validateFields()) {
				enviarEmail();
			}
		});*/
	// Evento de envio do formulário
$(".lp-ficaBem-form-wrapper #formCadastroLpFicaBem").on("submit", function (event) {
	event.preventDefault(); // Impede o envio tradicional
	if (validateFields()) {
		enviarEmail();
	}
});

	});

	// Função de validação completa
	function validateFields() {
		var isValid = true;

		 isValid &= validateField(".lp-ficaBem-form-wrapper #nome");
		isValid &= validateOnlyLetters(".lp-ficaBem-form-wrapper #nome", "Nome");

		isValid &= validateField(".lp-ficaBem-form-wrapper #email");
		 isValid &= validateEmail(".lp-ficaBem-form-wrapper #email");

		isValid &= validateField(".lp-ficaBem-form-wrapper #celular");

		isValid &= validateField(".lp-ficaBem-form-wrapper #empresa");
    isValid &= validateOnlyLetters(".lp-ficaBem-form-wrapper #empresa", "Empresa");

    isValid &= validateOnlyNumbers(".lp-ficaBem-form-wrapper #colaboradores", "Número de colaboradores");

		// Validação do reCAPTCHA (comentado)
		isValid &= validateRecaptcha();

		if (!isValid) {
			scrollIntoViewAdjusted($('.lp-ficaBem-form-wrapper .error-message')[0], 200);
		}

		return isValid;
	}

	// Função para validar campos obrigatórios
	 function validateField(selector) {
		 removeError(selector);

		 if ($(selector).val() == undefined || $(selector).val().trim() === "") {
			 $("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
			 $(selector).addClass("error-border").focus();
			 return false;
		 }

		 return true;
	 }

			// Função para validar apenas letras
			function validateOnlyLetters(selector, fieldName) {
  removeError(selector);

  const value = $(selector).val().trim();

  // Se o campo estiver vazio, exibe a mensagem de campo obrigatório
  if (value === "") {
    $("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
    $(selector).addClass("error-border").focus();
    return false;
  }

  // Validação de letras
  const regex = /^[A-Za-zÀ-ú\s]+$/;
  if (!regex.test(value)) {
    $("<p class='error-message'>*O campo " + fieldName + " deve conter apenas letras</p>").insertAfter(selector);
    $(selector).addClass("error-border").focus();
    return false;
  }

  return true;
}
      // Função para validar apenas números
function validateOnlyNumbers(selector, fieldName) {
  removeError(selector);

  const value = $(selector).val().trim();

  // Se o campo estiver vazio, exibe a mensagem de campo obrigatório
  if (value === "") {
    $("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
    $(selector).addClass("error-border").focus();
    return false;
  }

  // Validação de números
  const regex = /^[0-9]+$/;
  if (!regex.test(value)) {
    $("<p class='error-message'>*O campo " + fieldName + " deve conter apenas números</p>").insertAfter(selector);
    $(selector).addClass("error-border").focus();
    return false;
  }

  return true;
}


			// Validação de e-mail
			function validateEmail(selector) {
				removeError(selector);
				var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

				if (!emailRegex.test($(selector).val().trim())) {
					$("<p class='error-message'>*Digite um e-mail válido</p>").insertAfter(selector);
					$(selector).addClass("error-border").focus();
					return false;
				}

				return true;
			}

	// Função de reCAPTCHA (comentada)
	function validateRecaptcha() {
		$('.lp-ficaBem-form-wrapper .lp-ficaBem-recaptcha-container .error-message').remove();
		var recaptchaResponse = grecaptcha.getResponse();
		if (!recaptchaResponse || recaptchaResponse.length === 0) {
			$("<p class='error-message'>*Por favor, confirme que você não é um robô</p>")
				.appendTo('.lp-ficaBem-form-wrapper .lp-ficaBem-recaptcha-container');
			return false;
		}
		return true;
	}

	function removeError(selector) {
		$(selector).nextAll(".error-message").remove();
		$(selector).removeClass("error-border");
	}

			function scrollIntoViewAdjusted(elem, offset = 0) {
				try {
					if (elem) {
						window.scrollBy({
							top: elem.getBoundingClientRect().top - offset,
							behavior: "smooth"
						});
					}
				} catch (error) {
					console.error("Erro ao dar scroll até o campo inválido:", error);
				}
			}
	// Função para enviar email
	function enviarEmail() {
		$(".lp-ficaBem-form-wrapper #submitBtn").prop('disabled', true).text('Enviando...');
		$(".lp-ficaBem-form-wrapper #loadingDiv").show();

		const preFixoAssuntoEmail = "Novo Lead Fica bem";
		const nome = $("#nome").val();
		const email = $("#email").val();
		const celular = $("#celular").val();
		const empresa = $("#empresa").val();
		const numeroColaboradores = $("#colaboradores").val();

		const subject = `${preFixoAssuntoEmail}`;

		const template = `
    <body>
    <div>
        <p>Segue novo cadastro através da LP Fica bem:</p>

        <div>
            <div><strong>Nome:</strong> ${$("#nome").val()}</div>
            <div><strong>E-mail:</strong> ${$("#email").val()}</div>
            <div><strong>Celular:</strong> ${$("#celular").val()}</div>
            <div><strong>Empresa:</strong> ${$("#empresa").val()}</div>
            <div><strong>Número de Colaboradores:</strong> ${$("#colaboradores").val()}</div>
        </div>
    </div>
    </body>
    `;

		const cleanTemplate = template.replace(/\n/g, "").replace(/\s{2,}/g, " ");

		const data = {
			internalEmail: configuration.emailInterno,
			subject: subject,
			nome: $("#nome").val(),
			email: $("#email").val(),
			celular: $("#celular").val(),
			empresa: $("#empresa").val(),
			numeroColaboradores: $("#numeroColaboradores").val(),
			template: cleanTemplate
		};

		const apiURL = window.location.origin + "/api/servicos/generico/enviar-email-dinamico";

		console.log("Subject gerado:", subject);
		console.log("Dados enviados para API:", JSON.stringify(data, null, 2));

		$.ajax({
			url: apiURL,
			method: "POST",
			headers: {
				'Accept': 'application/json',
				'Content-Type': 'application/json'
			},
			data: JSON.stringify(data),
			success: function (res, textStatus, jqXHR) {
				$(".lp-ficaBem-form-wrapper #loadingDiv").hide();
				if (jqXHR.status === 200) {
					showSuccessMessage();
				} else {
					showErrorMessage("Erro ao enviar os dados.");
					resetSubmitButton();
				}
			},
			error: function (err) {
				console.error("Erro na requisição:", err);
				$(".lp-ficaBem-form-wrapper #loadingDiv").hide();

				var errorMessage = "Erro técnico ao enviar os dados.";
				if (err.status === 400) errorMessage = "Dados inválidos. Verifique os campos preenchidos.";
				else if (err.status === 401) errorMessage = "Sessão expirada. Recarregue a página e tente novamente.";
				else if (err.status === 500) errorMessage = "Erro interno do servidor. Tente novamente em alguns minutos.";

				showErrorMessage(errorMessage);
				resetSubmitButton();
			}
		});
	}

	function showSuccessMessage() {
		$(".lp-ficaBem-form-wrapper #formCadastroLpFicaBem").hide();
		$(".lp-ficaBem-form-wrapper #msgSucesso").css('display', 'flex');

		$(".lp-ficaBem-form-wrapper #formCadastro input").each(function () {
			$(this).val('');
		});

		grecaptcha.reset();
		scrollIntoViewAdjusted($('.lp-ficaBem-form-wrapper #msgSucesso')[0], 100);
	}

	function showErrorMessage(message) {
		alert(message);
	}

	function resetSubmitButton() {
		$(".lp-ficaBem-form-wrapper #submitBtn").prop('disabled', false).text('Enviar Cadastro');
	};

