$(document).ready(() => {
    if ($('body').hasClass('has-edit-mode-menu')) {
        return;
    }

    let observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                let $element = $(entry.target);
                let text = $element.text().trim();
                let match = text.match(/^([^\d]*)([\d,.]+)$/);

                if (!match) return;

                let prefix = match[1];
                let originalNumber = match[2];
                let hasComma = originalNumber.includes(',');
                let number = parseFloat(originalNumber.replace(',', '.'));
                const countInitialNumber = number / 2;

                // Impedir que a animação seja acionada mais de uma vez
                if ($element.data('animated')) return;
                $element.data('animated', true);

                $element.prop('Counter', countInitialNumber).animate({
                    Counter: number
                }, {
                    duration: 2000,
                    easing: 'swing',
                    step: function (now) {
                        let formattedNumber = hasComma 
                            ? now.toFixed(1).replace('.', ',')
                            : Math.ceil(now);
                        $element.text(prefix + formattedNumber);
                    }
                });
            }
        });
    }, { threshold: 0.5 });

    $('.sv-icone-texto .numero').each(function () {
        observer.observe(this);
    });
});;

