js:
setTimeout(function () {
  const middleBanner = document.getElementById("global-middle-banner");

  if (middleBanner) {
    middleBanner.style.display = "flex";
    const carouselSlides = middleBanner.querySelector(".carousel-slides");
    const slides = middleBanner.querySelectorAll(".carousel-slide");

    if (slides.length <= 1) {
      // Se houver apenas um slide, mostra sem inicializar o Slick
      slides[0].classList.add("active");
      slides[0].style.display = "flex";
      slides[0].style.visibility = "visible";
      slides[0].style.opacity = "1";
    } else {
      // Inicializa o Slick Carousel
      $(carouselSlides).slick({
        accessibility: false,
        dots: true,
        arrows: true,
        infinite: false,
        speed: 300,
        slidesToShow: 1,
        slidesToScroll: 1,
        autoplay: false,
        autoplaySpeed: 7000,
        pauseOnHover: true,
        pauseOnDotsHover: true,
        cssEase: "ease",
        prevArrow: middleBanner.querySelector(".prev"),
        nextArrow: middleBanner.querySelector(".next"),
        appendDots: middleBanner.querySelector(".pagination-container"),
        customPaging: function (slider, i) {
          return (
            '<button aria-label="Ir para o slide ' + (i + 1) + '"></button>'
          );
        },
        responsive: [
          {
            breakpoint: 9999,
            settings: {
              dots: true,
              arrows: true,
            },
          },
          {
            breakpoint: 1280,
            settings: {
              slidesToShow: 1,
              arrows: true,
              dots: true,
              adaptiveHeight: true,
            },
          },
          {
            breakpoint: 744,
            settings: {
              slidesToShow: 1,
              arrows: true,
              dots: true,
              adaptiveHeight: true,
            },
          },
        ],
      });

      // Função para corrigir aria-hidden e tabindex em slides focáveis
      function ajustarAcessibilidadeSlides() {
        $(carouselSlides)
          .find(".slick-slide")
          .each(function () {
            const isHidden = $(this).attr("aria-hidden") === "true";
            if (isHidden) {
              // Remove tabindex de elementos focáveis dentro de slides escondidos
              $(this)
                .find("[tabindex], a, button, input, textarea, select")
                .attr("tabindex", "-1");
            } else {
              // Restaura o tabindex original nos elementos visíveis
              $(this).find('[tabindex="-1"]').removeAttr("tabindex");
            }
          });
      }

      // Corrige logo após inicializar o slick
      ajustarAcessibilidadeSlides();

      // Corrige a cada mudança de slide
      $(carouselSlides).on("afterChange", function () {
        ajustarAcessibilidadeSlides();
      });

      // Adiciona classe 'disabled' nas setas quando necessário
      $(carouselSlides).on(
        "afterChange",
        function (event, slick, currentSlide) {
          const prevButton = middleBanner.querySelector(".prev");
          const nextButton = middleBanner.querySelector(".next");

          // Controle da seta anterior
          if (currentSlide === 0) {
            prevButton.classList.add("disabled");
            prevButton.disabled = true;
          } else {
            prevButton.classList.remove("disabled");
            prevButton.disabled = false;
          }

          // Controle da seta próxima
          if (currentSlide === slick.slideCount - 1) {
            nextButton.classList.add("disabled");
            nextButton.disabled = true;
          } else {
            nextButton.classList.remove("disabled");
            nextButton.disabled = false;
          }
        }
      );

      // Trigger inicial para configurar as setas
      $(carouselSlides).slick("slickGoTo", 0);
    }
  }
}, 500);;

